public sealed class NamingStandard { public string Source{get;set;}=""; public NamingFormat Format{get;set;}=new(); public List<NamingTab> Tabs{get;set;}=new(); public Dictionary<string,ManufacturerCode> Manufacturers{get;set;}=new(StringComparer.OrdinalIgnoreCase); public Dictionary<string,List<string>> FamilyHints{get;set;}=new(StringComparer.OrdinalIgnoreCase); }
