public sealed class CatalogAddRequest { public string TableName{get;set;}=""; public string Catalog{get;set;}=""; public string Manufacturer{get;set;}=""; public string Description{get;set;}=""; public string Type{get;set;}=""; public string Rating{get;set;}=""; public string User1{get;set;}=""; public string User2{get;set;}=""; public string User3{get;set;}=""; public string TextValue{get;set;}=""; public string WebLink{get;set;}=""; public string WdBlkNam{get;set;}=""; }
