public sealed class FootprintGeometry { public List<FootprintCurve> Curves{get;set;}=new(); public string Units{get;set;}="in"; public double MinX{get;set;}=double.MaxValue; public double MinY{get;set;}=double.MaxValue; public double MaxX{get;set;}=double.MinValue; public double MaxY{get;set;}=double.MinValue; public double Width=>MaxX-MinX; public double Height=>MaxY-MinY; }
